CREATE TABLE IF NOT EXISTS managed_projects (
  id TEXT PRIMARY KEY, name TEXT NOT NULL, path TEXT NOT NULL UNIQUE,
  created_at TEXT NOT NULL, position INTEGER NOT NULL
) STRICT;
CREATE TABLE IF NOT EXISTS managed_tasks (
  id TEXT PRIMARY KEY,
  project_id TEXT REFERENCES managed_projects(id) ON DELETE CASCADE,
  title TEXT NOT NULL, cwd TEXT NOT NULL,
  provider TEXT NOT NULL, session_id TEXT,
  updated_at REAL NOT NULL, pinned INTEGER NOT NULL CHECK(pinned IN (0,1)),
  archived INTEGER NOT NULL CHECK(archived IN (0,1)), status TEXT NOT NULL,
  UNIQUE(provider, session_id)
) STRICT;
CREATE INDEX IF NOT EXISTS managed_tasks_page ON managed_tasks(project_id, archived, updated_at DESC, id DESC);
CREATE INDEX IF NOT EXISTS managed_tasks_pinned ON managed_tasks(project_id, archived, pinned, updated_at DESC, id DESC);
CREATE TABLE IF NOT EXISTS managed_catalog_migration (id INTEGER PRIMARY KEY CHECK(id = 1)) STRICT;
